usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Containers.New(
		context.TODO(),
		openai.ContainerNewParams{
			Name: "string",
			FileIds: []string{"string"},
			ExpiresAfter: openai.CreateContainerBodyExpiresAfter{Anchor: "last_active_at", Minutes: 1},
			Skills: []openai.CreateContainerBodySkillsItem{openai.SkillReferenceParam{Type: "skill_reference", SkillID: "string", Version: "string"}},
			MemoryLimit: openai.CreateContainerBodyMemoryLimit1g,
			NetworkPolicy: openai.ContainerNetworkPolicyDisabledParam{Type: "disabled"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
